contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint beforeBank = c.bank().balance;
        uint beforePot = c.pot();
        uint beforeBalance = address(c).balance;

        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, msg.sender))) % 2;
        bool reverted;
        try c.play{value: 10}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBank = c.bank().balance;
        uint afterPot = c.pot();
        uint afterBalance = address(c).balance;

        assert(!reverted && ((random == 0 && afterPot == 0 && afterBank == beforeBank + 1 && afterBalance == beforeBalance + 1) || (random == 1 && afterPot == beforePot + 10 && afterBalance == beforeBalance + 10)));
    }

    receive() external payable {}
}

