        uint potBefore = c.pot();
        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
        if (reverted) {
            assert(address(c).balance == balBefore && c.pot() == potBefore);
        } else {
            assert(address(c).balance + (potBefore > 0 ? potBefore - 1 : 0) == balBefore || c.pot() == potBefore + amount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        uint potBefore = c.pot();
        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        uint potAfter = c.pot();
        assert(reverted ? (balAfter == balBefore && potAfter == potBefore) : (potBefore == 0 ? balAfter >= balBefore : balAfter + potBefore - 1 == balBefore));
    }

    receive() external payable {}
}
